import json, hashlib, pathlib

UUID = {"type": "string", "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"}
TEXT = {"type": "string", "minLength": 1}
INSTANT = {"type": "string", "minLength": 1}
DAY = {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}
STATUS = {"enum": ["scheduled", "arrived", "departed"]}

def items(required, properties):
    return {
        "type": "object",
        "required": required,
        "additionalProperties": False,
        "properties": properties,
    }

def envelope(required, properties, bounded=True):
    schema = {"type": "array"}
    if bounded:
        schema["minItems"] = 1
        schema["maxItems"] = 100
    schema["items"] = items(required, properties)
    return schema

OPERATIONS = [
    {
        "local": "carrier.create",
        "token": "dock:carrier/create@0.1.0",
        "wiring": "carrier_create",
        "path": "/carrier/create",
        "schema": envelope(["request_id", "name"], {"request_id": TEXT, "name": TEXT}),
    },
    {
        "local": "dock.create",
        "token": "dock:dock/create@0.1.0",
        "wiring": "dock_create",
        "path": "/dock/create",
        "schema": envelope(["request_id", "name"], {"request_id": TEXT, "name": TEXT}),
    },
    {
        "local": "appointment.book",
        "token": "dock:appointment/book@0.1.0",
        "wiring": "appointment_book",
        "path": "/appointment/book",
        "schema": envelope(
            ["request_id", "idempotency_key", "dock_id", "carrier_id", "slot_start", "slot_end"],
            {
                "request_id": TEXT,
                "idempotency_key": TEXT,
                "dock_id": UUID,
                "carrier_id": UUID,
                "slot_start": INSTANT,
                "slot_end": INSTANT,
            },
        ),
    },
    {
        "local": "appointment.check_in",
        "token": "dock:appointment/check-in@0.1.0",
        "wiring": "appointment_check_in",
        "path": "/appointment/check_in",
        "schema": envelope(
            ["request_id", "appointment_id", "arrived_at"],
            {"request_id": TEXT, "appointment_id": UUID, "arrived_at": INSTANT},
        ),
    },
    {
        "local": "appointment.query",
        "token": "dock:appointment/query@0.1.0",
        "wiring": "appointment_query",
        "path": "/appointment/query",
        "schema": envelope(
            ["request_id", "dock_id", "day"],
            {"request_id": TEXT, "dock_id": UUID, "day": DAY, "status": STATUS},
            bounded=False,
        ),
    },
]

root = pathlib.Path("packages/dock/publication")

declaration = {
    "scope": {
        "tenant-id": "__TENANT_ID__",
        "package-id": "dock",
        "package-version": "0.1.0",
    },
    "component": "dock",
    "interface-version": "0.1.0",
    "operations": {
        operation["token"]: {
            "registered-operation": operation["token"],
            "input-ports": [{"name": "input", "schema": operation["schema"]}],
            "output-ports": [{"name": "main", "schema": {"type": "array"}}],
            "parameters": [],
        }
        for operation in OPERATIONS
    },
    "connections": [],
}
(root / "components" / "dock.json.in").write_text(
    json.dumps(declaration, separators=(", ", ": ")) + "\n"
)

for operation in OPERATIONS:
    wiring = {
        "format-version": "0.1",
        "wiring-id": operation["wiring"],
        "version": 1,
        "entry": "operation",
        "nodes": {
            "operation": {
                "component": "dock",
                "interface-version": "0.1.0",
                "operation": operation["token"],
                "terminal": "respond",
            }
        },
    }
    (root / "wirings" / f"{operation['wiring']}.json").write_text(
        json.dumps(wiring, indent=2) + "\n"
    )

attachments = {}
for operation in OPERATIONS:
    attachment_id = "dock-" + operation["wiring"].replace("_", "-") + "-http"
    definition = {
        "id": attachment_id,
        "kind": "http",
        "route": {"path": operation["path"], "method": "POST"},
        "raw-body-bytes": {"maximum": 1048576},
        "input-schema": operation["schema"],
    }
    digest = hashlib.sha256(
        json.dumps(definition, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode()
    ).hexdigest()
    attachments[attachment_id] = {
        "kind": "http",
        "package-id": "dock",
        "wiring-id": operation["wiring"],
        "wiring-version": 1,
        "definition-hash": f"sha256:{digest}",
        "definition": definition,
        "auth-policy": {"mode": "pat"},
        "registered-operation": operation["token"],
    }

(root / "attachments.json").write_text(json.dumps(attachments, indent=2) + "\n")
print("written")
