import re, pathlib
lines = pathlib.Path("REPORT.md").read_text().split("\n")
inside = False
prose = []
buf = []
for line in lines:
    if line.startswith("```"):
        inside = not inside
        if buf:
            prose.append(" ".join(buf)); buf = []
        continue
    if inside or line.startswith("#") or line.startswith("- ") or line.startswith("  ") or re.match(r"^\d\.", line):
        if buf:
            prose.append(" ".join(buf)); buf = []
        continue
    if not line.strip():
        if buf:
            prose.append(" ".join(buf)); buf = []
        continue
    buf.append(line.strip())
if buf:
    prose.append(" ".join(buf))
sents = []
for para in prose:
    for s in re.split(r"(?<=[.?!])\s+", para):
        s = s.strip()
        if s:
            sents.append((len(s.split()), s))
sents.sort(reverse=True)
for n, s in sents[:6]:
    print(n, "|", s[:150])
bad = [x for x in sents if x[0] > 25]
print("over 25 words:", len(bad))
PY
